import json
def comps(g):
    h,w=len(g),len(g[0]); seen=[[False]*w for _ in range(h)]; out=[]
    for y in range(h):
        for x in range(w):
            if g[y][x] and not seen[y][x]:
                st=[(y,x)]; seen[y][x]=True; cells=[]
                while st:
                    a,b=st.pop(); cells.append((a,b))
                    for dy,dx in ((1,0),(-1,0),(0,1),(0,-1)):
                        ny,nx=a+dy,b+dx
                        if 0<=ny<h and 0<=nx<w and g[ny][nx] and not seen[ny][nx]:
                            seen[ny][nx]=True; st.append((ny,nx))
                out.append(cells)
    return out

