def rc(g):
    cs=[]; seen=[[0]*len(g[0]) for _ in range(len(g))]
    for y in range(len(g)):
        for x in range(len(g[0])):
            if g[y][x] and not seen[y][x]:
                cc=set(); st=[(y,x)]; seen[y][x]=1
                while st:
                    p,q=st.pop(); cc.add((p,q))
                    for dy in (-1,0,1):
                        for dx in (-1,0,1):
                            yy,xx=p+dy,q+dx
                            if 0<=yy<len(g) and 0<=xx<len(g[0]) and g[yy][xx] and not seen[yy][xx]:
                                seen[yy][xx]=1; st.append((yy,xx))
                cs.append(cc)
    return cs

