def solve(g):
    h,w=len(g),len(g[0]); o=[r[:] for r in g]
    cs=rc(g)
    bar=None
    for cc in cs:
        ys=[p[0] for p in cc]; xs_=[p[1] for p in cc]
        if len({g[p[0]][p[1]] for p in cc})>1 and max(max(ys)-min(ys)+1,max(xs_)-min(xs_)+1)<=4 and len(cc)<25:
            bar=cc
    seen=set(); seq=[]
    for y,x in sorted(bar,key=lambda p:(p[0],p[1])):
        v=g[y][x]
        if v not in seen: seen.add(v); seq.append(v)
    def sc(c): return {(y,x) for cc in cs if cc!=bar for y,x in cc if g[y][x]==c}
    masks={c:sc(c) for c in set(seq)}
    for i,v in enumerate(seq):
        right=[j for j,c in enumerate(set(seq)) if c!=v and len(masks[c])>3 and j>i]
        left=[j for j,c in enumerate(set(seq)) if c!=v and len(masks[c])>3 and j<i]
        if not right and not left: continue
        j = min(right) if right else max(left)
        pm=masks[seq[j]]
        t=min(y for y,x in pm); bot=max(y for y,x in pm)
        ph=bot-t+1
        if j>i:   # above: new bottom at t-1 -> top at t-ph
            dy=t-ph
        else:     # below: new top at bot+1
            dy=bot+1-t
        for y,x in pm:
            yy=y+dy
            if 0<=yy<h and o[yy][x]==0: o[yy][x]=v
    for y,x in bar: o[y][x]=0
    return o
